(() => {
const tiles=[...document.querySelectorAll('.tool-tile')],groups=[...document.querySelectorAll('[data-tool-group]')],filters=[...document.querySelectorAll('[data-tool-filter]')],count=document.querySelector('#toolFilterCount');
const dialog=document.querySelector('#toolModal'),title=document.querySelector('#toolModalTitle'),summary=document.querySelector('#toolModalSummary'),icon=document.querySelector('#toolModalIcon'),close=dialog.querySelector('.tool-dialog-close');
const reduced=matchMedia('(prefers-reduced-motion: reduce)');let trigger,animation,closing=false,previousOverflow='',offset={x:0,y:0};
function stopAnimation(){animation?.cancel();animation=null}
function openTool(tile){if(dialog.open)return;trigger=tile;closing=false;stopAnimation();title.textContent=tile.dataset.tool;summary.textContent=tile.dataset.description.replace(/\.+$/,'');dialog.style.setProperty('--tool-accent',tile.style.getPropertyValue('--tool-color'));icon.replaceChildren(tile.firstElementChild.cloneNode(true));
 tiles.forEach(t=>t.classList.toggle('tool-selected',t===tile));previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';dialog.showModal();close.focus({preventScroll:true});
 const source=tile.getBoundingClientRect(),target=dialog.getBoundingClientRect();offset={x:Math.max(-innerWidth*.4,Math.min(innerWidth*.4,source.left+source.width/2-target.left-target.width/2)),y:Math.max(-innerHeight*.35,Math.min(innerHeight*.35,source.top+source.height/2-target.top-target.height/2))};
 if(!reduced.matches)animation=dialog.animate([{opacity:0,transform:`translate(${offset.x}px,${offset.y}px) scale(.28) rotate(-3deg)`},{opacity:1,transform:'translate(0,0) scale(1.025) rotate(.3deg)',offset:.76},{opacity:1,transform:'translate(0,0) scale(1) rotate(0deg)'}],{duration:470,easing:'cubic-bezier(.2,.8,.2,1)'});
}
function closeTool(){if(!dialog.open||closing)return;closing=true;stopAnimation();if(reduced.matches){dialog.close();return}animation=dialog.animate([{opacity:1,transform:'translate(0,0) scale(1)'},{opacity:0,transform:`translate(${offset.x*.3}px,${offset.y*.3}px) scale(.78)`}],{duration:190,easing:'ease-in',fill:'forwards'});animation.onfinish=()=>dialog.close()}
tiles.forEach(tile=>tile.addEventListener('click',()=>openTool(tile)));close.addEventListener('click',closeTool);dialog.addEventListener('cancel',e=>{e.preventDefault();closeTool()});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeTool()});dialog.addEventListener('close',()=>{stopAnimation();closing=false;document.body.style.overflow=previousOverflow;tiles.forEach(t=>t.classList.remove('tool-selected'));trigger?.focus({preventScroll:true})});
filters.forEach(button=>button.addEventListener('click',()=>{filters.forEach(f=>f.setAttribute('aria-pressed',String(f===button)));let n=0,categories=0;groups.forEach(group=>{group.hidden=button.dataset.toolFilter!=='all'&&group.dataset.toolGroup!==button.dataset.toolFilter;if(!group.hidden){n+=group.querySelectorAll('.tool-tile').length;categories++}});count.textContent=`${n} tools · ${categories} ${categories===1?'category':'categories'}`;}));
})();
